insert into public.fragen (id, kapitel, format, text, fallen) values
('v1-01', '{"1"}'::smallint[], 'erklaere', 'Was ist der Unterschied zwischen „x := 5“ und „x = 5“? Nenne je eine Situation, in der man das eine bzw. das andere schreibt.', '{"begriff_unpraezise"}'::text[]),
('v1-02', '{"1"}'::smallint[], 'rechnung', 'Berechne ∑_{k=1}^{4} (2k − 1). Schreib die Summanden einzeln hin.', '{"rechenfehler"}'::text[]),
('v1-03', '{"1"}'::smallint[], 'rechnung', 'Berechne ∏_{k=2}^{4} k/(k−1). Fällt dir beim Ausschreiben etwas auf?', '{"rechenfehler"}'::text[]),
('v1-04', '{"1"}'::smallint[], 'janein', 'Stimmt ∑_{k=1}^{n} 3 = 3 für jedes n ∈ ℕ? Begründe.', '{"begriff_unpraezise","beispiel_beweis"}'::text[]),
('v1-05', '{"1"}'::smallint[], 'rechnung', 'Schreibe ∑_{k=2}^{5} a_k so um, dass der Laufindex bei 0 beginnt. Was passiert mit den Grenzen und mit dem Index von a?', '{"rechenfehler"}'::text[]),
('v1-06', '{"1"}'::smallint[], 'erklaere', 'Erkläre in eigenen Worten die Idee hinter Gauß'' Herleitung von 1 + 2 + … + n, so wie du sie in der Prüfung an der Tafel skizzieren würdest.', '{"begriff_unpraezise"}'::text[]),
('v1-07', '{"1"}'::smallint[], 'anwendung', 'Programm A summiert 1 bis n mit einer Schleife, Programm B benutzt eine geschlossene Formel. Was bedeutet der Unterschied, wenn n sehr groß wird?', '{"begruendung_fehlt"}'::text[]),
('v1-08', '{"1"}'::smallint[], 'rechnung', 'Berechne 1 + 2 + … + 60, ohne alle Zahlen zu addieren. Welche Formel nutzt du, und warum darfst du sie hier anwenden?', '{"rechenfehler"}'::text[]),
('v1-09', '{"1"}'::smallint[], 'janein', 'In einem verschachtelten Ausdruck ∑_{k} ∏_{j} … : Darf die obere Grenze der äußeren Summe vom inneren Index j abhängen? Begründe.', '{"begriff_unpraezise"}'::text[]),
('v2-01', '{"2"}'::smallint[], 'erklaere', 'Was ist eine Menge? Erkläre damit, warum {1, 2, 2} und {2, 1} dieselbe Menge sind.', '{"begriff_unpraezise"}'::text[]),
('v2-02', '{"2"}'::smallint[], 'janein', 'Ist 0 ∈ ℕ? Wovon hängt die Antwort ab, und was gilt in dieser Vorlesung? Begründe mit den Peano-Axiomen.', '{"n_vs_n0"}'::text[]),
('v2-03', '{"2"}'::smallint[], 'rechnung', 'A = {2, 4, 6, 8}, B = {1, 2, 3, 4}, C = {7}. Bestimme A ∩ B, A ∪ C und B \ A.', '{"rechenfehler"}'::text[]),
('v2-04', '{"2"}'::smallint[], 'janein', 'Jemand schreibt für zwei Mengen A und B den Ausdruck „A ∨ B“. Ist das korrekte Notation? Was meint die Person vermutlich?', '{"oder_vereinigung"}'::text[]),
('v2-05', '{"2"}'::smallint[], 'rechnung', 'Wie viele Elemente hat P({a, b, c})? Nenne drei der Elemente und begründe die Anzahl.', '{"rechenfehler"}'::text[]),
('v2-06', '{"2"}'::smallint[], 'janein', 'Gilt für jede Menge M sowohl ∅ ∈ P(M) als auch ∅ ⊂ M? Begründe beide Teile getrennt.', '{"begriff_unpraezise"}'::text[]),
('v2-07', '{"2"}'::smallint[], 'janein', 'Vergleiche „∀ k ∈ ℤ ∃ m ∈ ℤ: k + m = 0“ mit „∃ m ∈ ℤ ∀ k ∈ ℤ: k + m = 0“. Welche Aussage ist wahr? Begründe.', '{"quantoren"}'::text[]),
('v2-08', '{"2"}'::smallint[], 'alltag', 'Verneine den Satz „Heute regnet es oder ich fahre Rad.“ Welche Regel benutzt du?', '{"begriff_unpraezise"}'::text[]),
('v2-09', '{"2"}'::smallint[], 'erklaere', 'Was bedeutet „tertium non datur“? Nenne ein Gebiet, in dem man bewusst davon abweicht.', '{"begriff_unpraezise"}'::text[]),
('v2-10', '{"2"}'::smallint[], 'rechnung', 'Setze in ¬A ∨ B ∧ C alle Klammern so, wie es die Rangfolge der Operatoren vorgibt.', '{"rechenfehler"}'::text[]),
('v2-11', '{"2"}'::smallint[], 'anwendung', 'Ein Chip hat 4 Transistoren, die jeweils an oder aus sind. Wie viele Zustände gibt es, und was hat das mit der Potenzmenge zu tun?', '{"begruendung_fehlt"}'::text[]),
('v3-01', '{"3"}'::smallint[], 'erklaere', 'Wann genau ist A ⇒ B falsch? Erkläre, warum „aus Falschem folgt alles“ mit dieser Definition zusammenpasst.', '{"impl_richtung"}'::text[]),
('v3-02', '{"3"}'::smallint[], 'alltag', 'Bilde zu „Wenn ich die HA abgebe, bekomme ich Punkte“ die Kontraposition und die Umkehrung. Welche davon ist gleichwertig zur Ausgangsaussage?', '{"impl_richtung"}'::text[]),
('v3-03', '{"3"}'::smallint[], 'janein', '„Die Straße ist nass, also hat es geregnet.“ Ist das ein korrekter Schluss aus „Wenn es regnet, ist die Straße nass“? Begründe.', '{"impl_richtung"}'::text[]),
('v3-04', '{"3"}'::smallint[], 'erklaere', 'Wie unterscheiden sich direkter Beweis, Beweis durch Kontraposition und Widerspruchsbeweis? Woran erkennst du, welche Methode sich anbietet?', '{"vor_beh"}'::text[]),
('v3-05', '{"3"}'::smallint[], 'janein', 'Ein Kommilitone prüft eine Formel für n = 1, 2, 3 und schreibt „gilt also für alle n ∈ ℕ“. Ist das ein Beweis? Was fehlt?', '{"beispiel_beweis","induktion_konkret"}'::text[]),
('v3-06', '{"3"}'::smallint[], 'erklaere', 'Erkläre die vollständige Induktion mit dem Domino-Bild: Was entspricht dem ersten Stein, was dem Umstoßen, und warum reicht das?', '{"induktion_konkret"}'::text[]),
('v3-07', '{"3"}'::smallint[], 'rechnung', 'Berechne ∑_{k=0}^{4} 3^k einmal mit der geometrischen Summenformel und kontrolliere es durch Ausschreiben.', '{"rechenfehler","n_vs_n0"}'::text[]),
('v3-08', '{"3"}'::smallint[], 'janein', 'Darf man die geometrische Summenformel mit dem Bruch auch für x = 1 benutzen? Was macht man in diesem Fall?', '{"definitionsbereich"}'::text[]),
('v3-09', '{"3"}'::smallint[], 'erklaere', 'Skizziere mündlich die Beweisidee dafür, dass √2 nicht rational ist. An welcher Stelle entsteht der Widerspruch?', '{"vor_beh"}'::text[]),
('v3-10', '{"3"}'::smallint[], 'erklaere', 'Was darf man bei der starken Induktion zusätzlich voraussetzen? Nenne eine Aussage, bei der man das wirklich braucht.', '{"induktion_konkret"}'::text[]),
('v3-11', '{"3"}'::smallint[], 'janein', 'Ist „r ∈ ℚ ⇔ es gibt q ∈ ℤ mit qr ∈ ℤ“ eine wahre Äquivalenz? Prüfe beide Richtungen einzeln.', '{"impl_richtung"}'::text[]),
('v4-01', '{"4"}'::smallint[], 'rechnung', 'A = {x, y}, B = {1, 2}. Bestimme A × B und |B × A|. Ist A × B = B × A?', '{"rechenfehler"}'::text[]),
('v4-02', '{"4"}'::smallint[], 'erklaere', 'Was ist eine Relation formal? Wo begegnen dir Relationen in der Informatik?', '{"begriff_unpraezise"}'::text[]),
('v4-03', '{"4"}'::smallint[], 'janein', 'Ist „<“ auf ℤ eine Partialordnung? Prüfe jede der drei Eigenschaften einzeln.', '{"begriff_unpraezise","beispiel_beweis"}'::text[]),
('v4-04', '{"4"}'::smallint[], 'janein', 'Ist die Teilbarkeitsrelation „|“ auf ℤ \ {0} antisymmetrisch? Beweise deine Antwort oder gib ein Gegenbeispiel.', '{"definitionsbereich"}'::text[]),
('v4-05', '{"4"}'::smallint[], 'rechnung', 'Gilt 38 ≡ 14 mod 6? Begründe über die Definition der Kongruenz.', '{"mod_kongruenz"}'::text[]),
('v4-06', '{"4","5"}'::smallint[], 'erklaere', 'Was ist der Unterschied zwischen „a mod m = b“ und „a ≡ b mod m“? Gib ein Beispiel, bei dem das eine gilt und das andere nicht.', '{"mod_kongruenz"}'::text[]),
('v4-07', '{"4"}'::smallint[], 'janein', 'Auf der Menge aller Menschen sei x ∼ y, wenn x und y sich persönlich kennen. Ist das eine Äquivalenzrelation?', '{"beispiel_beweis"}'::text[]),
('v4-08', '{"4"}'::smallint[], 'rechnung', 'Gib mindestens fünf Elemente der Äquivalenzklasse [3] modulo 4 an, darunter negative. Wie schreibt man die Klasse kompakt?', '{"rechenfehler"}'::text[]),
('v4-09', '{"4"}'::smallint[], 'erklaere', 'Warum sind zwei Äquivalenzklassen entweder disjunkt oder gleich? Skizziere die Beweisidee und nenne die Eigenschaften, die du dabei benutzt.', '{"vor_beh"}'::text[]),
('v4-10', '{"4"}'::smallint[], 'rechnung', 'f: ℝ → ℝ, x ↦ x². Bestimme f⁻¹({4}), f⁻¹({−1}) und das Bild f(ℝ).', '{"definitionsbereich"}'::text[]),
('v4-11', '{"4"}'::smallint[], 'janein', 'Ist die Vorschrift „x ↦ ±√x“ von [0, ∞) nach ℝ eine Abbildung? Begründe mit der Definition.', '{"begriff_unpraezise"}'::text[]),
('v5-01', '{"5"}'::smallint[], 'rechnung', 'Berechne ⌊−2,5⌋, ⌈−2,5⌉ und ⌊3⌋.', '{"rechenfehler"}'::text[]),
('v5-02', '{"5"}'::smallint[], 'rechnung', 'Berechne −17 div 5 und −17 mod 5 nach der Definition aus der VL. Liefert Java mit / und % dasselbe?', '{"mod_kongruenz","rechenfehler"}'::text[]),
('v5-03', '{"5"}'::smallint[], 'rechnung', 'Berechne ggT(210, 84) mit dem Euklidischen Algorithmus. Schreib jeden rekursiven Aufruf hin.', '{"rechenfehler"}'::text[]),
('v5-04', '{"5"}'::smallint[], 'erklaere', 'Warum terminiert der Euklidische Algorithmus immer? Welche Eigenschaft von a mod b ist dafür entscheidend?', '{"begruendung_fehlt"}'::text[]),
('v5-05', '{"5"}'::smallint[], 'rechnung', 'f(0) := 2 und f(n) := 3 · f(n − 1) − 1 für n ≥ 1. Berechne f(3) Schritt für Schritt.', '{"rechenfehler","n_vs_n0"}'::text[]),
('v5-06', '{"5"}'::smallint[], 'janein', 'Gilt ⌊−x⌋ = −⌊x⌋ für alle x ∈ ℝ? Begründe.', '{"beispiel_beweis"}'::text[]),
('v5-07', '{"5"}'::smallint[], 'erklaere', 'Erkläre die Dreiecksungleichung |a − b| ≤ |a − c| + |c − b| geometrisch, ohne Formeln vorzulesen.', '{"begriff_unpraezise"}'::text[]),
('v5-08', '{"5"}'::smallint[], 'janein', 'Für welche n ∈ ℕ₀ ist n! eine Primzahl? Begründe, warum es keine weiteren gibt.', '{"n_vs_n0","beispiel_beweis"}'::text[]),
('v5-09', '{"5"}'::smallint[], 'erklaere', 'Die Definition des ggT hat zwei Bedingungen. Warum reicht es nicht, einfach „der größte gemeinsame Teiler“ zu sagen?', '{"begriff_unpraezise"}'::text[]),
('v5-10', '{"5"}'::smallint[], 'anwendung', 'Warum ist es für die Informatik wichtig, die maximale Anzahl rekursiver Aufrufe eines Algorithmus abschätzen zu können?', '{"begruendung_fehlt"}'::text[]),
('v5-11', '{"5"}'::smallint[], 'janein', 'Gilt sgn(x) · x = |x| auch für x = 0 mit der Signum-Definition aus der VL? Begründe.', '{"definitionsbereich"}'::text[]),
('v6-01', '{"6"}'::smallint[], 'rechnung', 'f(n) = 2n und g(n) = n + 3 auf ℕ. Berechne (g ∘ f)(n) und (f ∘ g)(n). Ist die Verkettung hier kommutativ?', '{"rechenfehler"}'::text[]),
('v6-02', '{"6"}'::smallint[], 'erklaere', 'Erkläre injektiv und surjektiv in eigenen Worten und gib zu jedem Begriff ein eigenes Beispiel und ein Gegenbeispiel.', '{"begriff_unpraezise"}'::text[]),
('v6-03', '{"6"}'::smallint[], 'janein', 'f: ℤ → ℤ, n ↦ 2n. Ist f injektiv? Ist f surjektiv? Beweise beides.', '{"definitionsbereich","beispiel_beweis"}'::text[]),
('v6-04', '{"6"}'::smallint[], 'janein', 'Vergleiche f: ℤ → ℤ, n ↦ 2n mit g: ℝ → ℝ, x ↦ 2x. Sind f und g jeweils injektiv und surjektiv? Was ändert sich zwischen den beiden, und warum?', '{"definitionsbereich"}'::text[]),
('v6-05', '{"6"}'::smallint[], 'rechnung', 'Bestimme die Umkehrfunktion von f: ℝ → ℝ, x ↦ 3x − 5, und prüfe beide Verkettungen.', '{"rechenfehler","begruendung_fehlt"}'::text[]),
('v6-06', '{"6"}'::smallint[], 'erklaere', 'Warum gilt (g ∘ f)⁻¹ = f⁻¹ ∘ g⁻¹ und nicht g⁻¹ ∘ f⁻¹? Erkläre es anschaulich.', '{"begriff_unpraezise"}'::text[]),
('v6-07', '{"6"}'::smallint[], 'rechnung', 'A = {x ∈ ℝ; 0 < x ≤ 2}. Bestimme sup A und inf A. Existieren max A und min A?', '{"definitionsbereich"}'::text[]),
('v6-08', '{"6"}'::smallint[], 'anwendung', 'Was bedeutet „ℚ liegt dicht in ℝ“, und warum ist das für das Rechnen am Computer relevant?', '{"begriff_unpraezise"}'::text[]),
('v6-09', '{"6"}'::smallint[], 'janein', 'Hat jede nach oben beschränkte, nichtleere Teilmenge von ℚ ein Supremum in ℚ? Begründe oder nenne ein Gegenbeispiel.', '{"definitionsbereich"}'::text[]),
('v6-10', '{"6"}'::smallint[], 'janein', 'Hat f: ℝ → [0, ∞), x ↦ x² eine Umkehrfunktion? Was müsste man ändern, damit es eine gibt?', '{"definitionsbereich"}'::text[]),
('v7-01', '{"7"}'::smallint[], 'janein', 'Ist (ℤ, ·) eine Gruppe? Welche Gruppeneigenschaft prüfst du zuerst, und woran scheitert es gegebenenfalls?', '{"begriff_unpraezise"}'::text[]),
('v7-02', '{"7"}'::smallint[], 'erklaere', 'Erkläre den Aufbau Gruppe → abelsche Gruppe → Ring → Körper: Was kommt bei jedem Schritt dazu?', '{"begriff_unpraezise"}'::text[]),
('v7-03', '{"7"}'::smallint[], 'rechnung', 'Stelle für {0, 1, 2, 3} mit a ⊕ b := (a + b) mod 4 die Verknüpfungstafel auf. Lies das neutrale Element und das Inverse von 3 ab.', '{"rechenfehler"}'::text[]),
('v7-04', '{"7"}'::smallint[], 'janein', 'Ist ({1, 2, 3}, (a · b) mod 4) eine Gruppe? Welche Eigenschaft prüfst du zuerst?', '{"beispiel_beweis"}'::text[]),
('v7-05', '{"7"}'::smallint[], 'rechnung', 'Bringe (2 + 3i)(1 − i) in die Form a + ib.', '{"rechenfehler"}'::text[]),
('v7-06', '{"7"}'::smallint[], 'rechnung', 'Bringe 1/(1 + i) in die Form a + ib. Welcher Trick hilft beim Nenner?', '{"rechenfehler"}'::text[]),
('v7-07', '{"7"}'::smallint[], 'janein', 'Gilt √(z · w) = √z · √w für alle Zahlen z, w? Begründe, und sag, wann die Regel gilt.', '{"definitionsbereich"}'::text[]),
('v7-08', '{"7"}'::smallint[], 'erklaere', 'Warum erweitert man ℝ zu ℂ? An welche Grenze stößt ℝ, und was muss der neue Körper leisten?', '{"begriff_unpraezise"}'::text[]),
('v7-09', '{"7"}'::smallint[], 'rechnung', 'z = 4 − 5i. Bestimme Re z, Im z, z̄ und z · z̄. Was fällt dir an z · z̄ auf?', '{"rechenfehler"}'::text[]),
('v7-10', '{"7"}'::smallint[], 'anwendung', 'Die Bits {0, 1} mit XOR und AND bilden einen Körper. Wo in der Informatik begegnet dir das?', '{"begruendung_fehlt"}'::text[]),
('v7-11', '{"7"}'::smallint[], 'janein', 'Ist (ℕ₀, +) eine Gruppe? Und (ℤ, +)? Begründe den Unterschied.', '{"n_vs_n0"}'::text[]),
('x-01', '{"3","5"}'::smallint[], 'verknuepfung', 'Was haben vollständige Induktion und rekursive Funktionen gemeinsam? Erkläre es am Beispiel der Fakultät.', '{"induktion_konkret"}'::text[]),
('x-02', '{"4","5"}'::smallint[], 'verknuepfung', 'Wie hängen die Kongruenz modulo m, Äquivalenzklassen und der mod-Operator zusammen?', '{"mod_kongruenz"}'::text[]),
('x-03', '{"2","4"}'::smallint[], 'verknuepfung', 'Die Teilmengenrelation ⊂ auf P(M): Welche Ordnungseigenschaften hat sie, und warum ist sie im Allgemeinen keine Totalordnung?', '{"beispiel_beweis"}'::text[]),
('x-04', '{"3","6"}'::smallint[], 'verknuepfung', 'Injektivität lässt sich auf zwei Arten formulieren. Welche Beweistechnik aus VL3 verbindet die beiden Formulierungen?', '{"impl_richtung"}'::text[]),
('x-05', '{"6","7"}'::smallint[], 'verknuepfung', 'Ein inverses Element in einer Gruppe und eine Umkehrfunktion: Was ist die gemeinsame Idee, und wo liegt der Unterschied?', '{"begriff_unpraezise"}'::text[])
