-- Fragenpool und Glossar-Begriffe (nur Fragen/Begriffe, KEINE Lösungen)
-- Quelle: bestehender Mathe-1-Trainer (eigene Zusammenfassungen), Kursbezug neutralisiert.

on conflict (id) do update set kapitel = excluded.kapitel, format = excluded.format, text = excluded.text, fallen = excluded.fallen;

on conflict (id) do update set begriff = excluded.begriff, kapitel = excluded.kapitel;
